  // Multiply the baseline animation scale by our calculated responsive layout scale
  const phoneScale = interpolate(phoneEntranceSpring, [0, 1], [0.95, 1]);
  const combinedScale = phoneScale * layoutScale;
  const phoneOpacity = interpolate(phoneEntranceSpring, [0, 1], [0, 1]);

  const timestampOpacity = interpolate(frame, [15, 25], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const timestampY = interpolate(frame, [15, 25], [10, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const messageSpring = spring({
    frame: frame - 25,
    fps,
    config: { damping: 14, mass: 0.6 },
  });
  const messageScale = interpolate(messageSpring, [0, 1], [0.85, 1]);
  const messageOpacity = interpolate(messageSpring, [0, 1], [0, 1]);
  const messageY = interpolate(messageSpring, [0, 1], [20, 0]);

  const footerOpacity = interpolate(frame, [45, 55], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const footerY = interpolate(frame, [45, 55], [10, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

